 private static final Map<Integer,int[]> custom=new HashMap<>();
 public static void put(int id,int[] v){if(id<0||id>0x1FFFFFFF||v.length!=16)throw new IllegalArgumentException("CAN ID / table invalid");for(int x:v)if(x<0||x>255)throw new IllegalArgumentException("Byte out of range");custom.put(id,v.clone());}
 public static void remove(int id){custom.remove(id);}
 public static Map<Integer,int[]> customTables(){return custom;}
 public static void clearCustom(){custom.clear();}
 public static Map<Integer,int[]> builtinTables(){Map<Integer,int[]> m=new HashMap<>();for(int[] a:TABLE)m.put(a[0],Arrays.copyOfRange(a,1,17));return m;}
 public static int[] get(int id){if(custom.containsKey(id))return custom.get(id).clone();for(int[] a:TABLE)if(a[0]==id)return Arrays.copyOfRange(a,1,17);return null;}
 public static byte[] parseHex(String s){s=s.replaceAll("(?i)0x","").replaceAll("[\\s,;:_-]","");if(s.length()==0||s.length()%2!=0||!s.matches("[0-9a-fA-F]+"))throw new IllegalArgumentException("Неверные HEX-байты");byte[] b=new byte[s.length()/2];for(int i=0;i<b.length;i++)b[i]=(byte)Integer.parseInt(s.substring(i*2,i*2+2),16);return b;}
 public static int[] parseTable(String s){byte[] b=parseHex(s);if(b.length!=16)throw new IllegalArgumentException("Требуется 16 байт");int[] a=new int[16];for(int i=0;i<16;i++)a[i]=b[i]&255;return a;}
 public static String tableHex(int[] t){StringBuilder s=new StringBuilder();for(int x:t){if(s.length()>0)s.append(' ');s.append(String.format(Locale.ROOT,"%02X",x));}return s.toString();}
 private static int step(int c){for(int i=0;i<8;i++)c=((c&128)!=0?(c<<1)^0x2F:c<<1)&255;return c;}
 public static int calculate(int id,byte[] p){if(p.length<2||p.length>8)throw new IllegalArgumentException("Длина 2–8 байт");int[] t=get(id);if(t==null)throw new IllegalArgumentException("Нет таблицы для CAN ID");int crc=255;for(int i=1;i<p.length;i++)crc=step(crc^(p[i]&255));return step(crc^t[p[1]&15])^255;}
